INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('2131f566-cede-43c0-9273-3c698fd0c245', '00000000-0000-0000-0000-000000000001', 'inafectacion_arbitrio', 'Inafectación de arbitrio', 'Inafectaciones de arbitrio', 'Un predio que no paga un servicio en un periodo (por ejemplo, sin recojo de residuos). Se mira a la fecha de cada mes; es solo de arbitrios, no la condición especial del predial.', true, 'inafectacion_arbitrio__00000000', '2026-10-19 21:57:52.097405+00', '2026-10-19 21:57:52.097405+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('a8f54ebe-41f1-49b0-9c24-4809f324ebb8', '00000000-0000-0000-0000-000000000001', 'anuncio', 'Anuncio', 'Anuncios', 'Un anuncio o propaganda autorizado. No se edita: su estado se deriva de sus movimientos. Solo se agrega.', true, 'anuncio__00000000', '2026-10-19 21:58:09.849181+00', '2026-10-19 21:58:09.849181+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('efe40440-886d-43a0-a812-1b21360cae32', '00000000-0000-0000-0000-000000000001', 'determinacion_arbitrio_masiva', 'Determinación masiva de arbitrios', 'Determinaciones masivas de arbitrios', 'La determinación en segundo plano de los arbitrios de un año, por lotes de predios, en cualquier instancia (como emision_masiva). No genera archivo.', true, 'determinacion_arbitrio_masiva__00000000', '2026-10-19 21:57:56.091179+00', '2026-10-19 21:57:56.091179+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('da8b427f-71d2-4b9b-a1c2-e80cbafb55b6', '00000000-0000-0000-0000-000000000001', 'determinacion_arbitrio_lote', 'Lote de determinación de arbitrios', 'Lotes de determinación de arbitrios', 'Un tramo de los predios de una determinación masiva, que toma un trabajador de cualquier instancia (como emision_lote).', true, 'determinacion_arbitrio_lote__00000000', '2026-10-19 21:57:57.561195+00', '2026-10-19 21:57:57.561195+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('18d054d0-55da-429e-b5d2-9fd931fa088d', '00000000-0000-0000-0000-000000000001', 'codigo_infraccion', 'Código de infracción', 'Códigos de infracción', 'El CUIS, versionado por vigencia: un cambio cierra la versión vigente (vigencia_hasta, clave_vigente) y agrega la nueva. Ningún otro campo se edita. Lo escribe solo el servicio de srtm.', true, 'codigo_infraccion__00000000', '2026-10-19 21:57:58.95273+00', '2026-10-19 21:57:58.95273+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('8db29077-139a-4bd4-bf91-281cf2f90c72', '00000000-0000-0000-0000-000000000001', 'notificacion_administrativa', 'Notificación administrativa', 'Notificaciones administrativas', 'La notificación previa a un acta. Vencida se deriva de fecha y plazo_dias, no se guarda. Solo se agrega.', true, 'notificacion_administrativa__00000000', '2026-10-19 21:58:00.501109+00', '2026-10-19 21:58:00.501109+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('c76d2770-698b-41dc-8b16-fb5b28a4d129', '00000000-0000-0000-0000-000000000001', 'subsanacion_notificacion', 'Subsanación de notificación', 'Subsanaciones de notificaciones', 'La subsanación de una notificación previa: una por notificación. Solo se agrega.', true, 'subsanacion_notificacion__00000000', '2026-10-19 21:58:01.334116+00', '2026-10-19 21:58:01.334116+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('6cf6eb6f-5fc5-40ab-88fc-7c627927d414', '00000000-0000-0000-0000-000000000001', 'papeleta', 'Acta de infracción', 'Actas de infracción', 'El acta de una infracción administrativa, con su multa calculada y congelada. No se edita ni se borra: se anula agregando una anulación. Lo escribe solo el servicio de srtm.', true, 'papeleta__00000000', '2026-10-19 21:58:02.398603+00', '2026-10-19 21:58:02.398603+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('fe981cdd-2923-47f5-85e4-9d9e238f22cb', '00000000-0000-0000-0000-000000000001', 'anulacion_papeleta', 'Anulación de acta', 'Anulaciones de actas', 'La anulación de un acta: una por acta. Solo se agrega.', true, 'anulacion_papeleta__00000000', '2026-10-19 21:58:04.696063+00', '2026-10-19 21:58:04.696063+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('72beb1e6-4c7f-417c-9874-fb1c394bee2b', '00000000-0000-0000-0000-000000000001', 'descargo_papeleta', 'Descargo', 'Descargos', 'Un descargo o recurso contra un acta, con su plazo resuelto una vez y copiado. El tardío se registra. Solo se agrega.', true, 'descargo_papeleta__00000000', '2026-10-19 21:58:05.484848+00', '2026-10-19 21:58:05.484848+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('ab98718c-e75e-4245-8982-4c8b49f7601c', '00000000-0000-0000-0000-000000000001', 'resolucion_gerencia', 'Resolución de gerencia', 'Resoluciones de gerencia', 'La resolución que sanciona un acta (ADMINISTRATIVA, una por acta) o resuelve un descargo (RECURSO, una por descargo). Su PDF se regenera de lo guardado. Solo se agrega.', true, 'resolucion_gerencia__00000000', '2026-10-19 21:58:06.620481+00', '2026-10-19 21:58:06.620481+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('07764e37-2864-4a07-a65d-ffd8656f8f46', '00000000-0000-0000-0000-000000000001', 'notificacion_resolucion', 'Notificación de resolución', 'Notificaciones de resoluciones', 'Cada intento de notificar una resolución. La que surte efecto (NOTIFICADO o RECHAZADO) lleva exigible_desde, calculado en días hábiles y copiado. Solo se agrega.', true, 'notificacion_resolucion__00000000', '2026-10-19 21:58:08.037544+00', '2026-10-19 21:58:08.037544+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('648adcea-078e-4e2e-b308-22f2eb042802', '00000000-0000-0000-0000-000000000001', 'brecha_corrida', 'Corrida de brecha de recaudación', 'Corridas de brecha de recaudación', 'Una medición de la brecha de recaudación de un año: el padrón (DJ) contra las valuaciones de catastro-backend, en segundo plano. Una activa por año.', true, 'brecha_corrida__00000000', '2026-10-19 21:58:14.370877+00', '2026-10-19 21:58:14.370877+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('4419039e-2d9e-4c79-bbc6-1c8c82b7ee6e', '00000000-0000-0000-0000-000000000001', 'brecha_predio', 'Predio de la brecha', 'Predios de la brecha', 'Un predio de una corrida de brecha: su categoría (omiso, subvaluado...) y sus diferencias de autoavalúo, impuesto predial y arbitrios.', true, 'brecha_predio__00000000', '2026-10-19 21:58:16.034196+00', '2026-10-19 21:58:16.034196+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('ade95cdb-a8ae-4d28-996a-85789e266b5e', '00000000-0000-0000-0000-000000000001', 'anulacion_cuota_arbitrio', 'Anulación de cuota de arbitrio', 'Anulaciones de cuotas de arbitrio', 'La corrección de una cuota de arbitrio: se agrega, nunca se edita ni se borra. La cuota anulada deja de contar, y la redeterminación del predio escribe la versión siguiente de su clave.', true, 'anulacion_cuota_arbitrio__00000000', '2026-10-19 21:57:55.038054+00', '2026-10-19 21:59:54.742966+00', '[]', '[]', true, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('af1f7962-19b2-409d-9b50-63b6f95929d5', '00000000-0000-0000-0000-000000000001', 'movimiento_anuncio', 'Movimiento de anuncio', 'Movimientos de anuncios', 'Un acto sobre un anuncio: la autorización y la renovación devengan la tasa del ejercicio; el cese y el retiro llevan motivo. Solo se agrega.', true, 'movimiento_anuncio__00000000', '2026-10-19 21:58:11.711428+00', '2026-10-19 21:58:11.711428+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('6555d58c-3a84-4b11-a3d1-623f656dd6d4', '00000000-0000-0000-0000-000000000001', 'zona_arbitrio_ubicacion', 'Zona de arbitrio por ubicación', 'Zonas de arbitrio por ubicación', 'Una zona por vía, tramo (rango de número y paridad) y manzana, opcionalmente de un solo servicio. Más precisa que el sector catastral de ARBITRIO_ZONA, y se intenta primero (Zonas.de).', true, 'zona_arbitrio_ubicacion__00000000', '2026-10-19 21:58:12.900707+00', '2026-10-19 21:58:12.900707+00', '[]', '[]', false, false, false);
INSERT INTO wasichai.custom_objects (id, organization_id, name, label, plural_label, description, enabled, physical_table, created_at, updated_at, indexes, unique_constraints, append_only, api_only, requires_reason) VALUES ('ba704775-88aa-4afb-9da1-549b48e5212a', '00000000-0000-0000-0000-000000000001', 'cuota_arbitrio', 'Cuota de arbitrio', 'Cuotas de arbitrio', 'Lo determinado de un servicio, un predio, un uso (secuencia) y un mes, con su desglose. Inmutable: nunca se edita ni se borra (una corrección es una anulación que se agrega). No es deuda: es lo determinado a su fecha_calculo.', true, 'cuota_arbitrio__00000000', '2026-10-19 21:57:53.074836+00', '2026-10-19 21:59:53.15557+00', '[["anio", "predio"], ["anio", "contribuyente"]]', '[]', true, false, false);
